package dev.hoi.client.map;

import dev.hoi.client.ClientCampaignHud;
import dev.hoi.client.screen.ScreenMapCursor;
import dev.hoi.protocol.*;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import dev.hoi.protocol.ProtocolCommanderOrders.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;

final class MapSelectionDetailsTest {
    private MapSelectionDetailsTest() {}
    private static int scroll(){try{var f=MapCommanderPanels.class.getDeclaredField("scroll");f.setAccessible(true);return f.getInt(null);}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
    private static Set<String> rows(){return MapCommanderPanels.selectedDivisionRows().stream().map(Member::id).collect(java.util.stream.Collectors.toSet());}
    static void run(ClientGameTestContext game,ProtocolMenuView menu){
        branches(game,menu);
        var selections=new ArrayList<Selection>();var sounds=new ArrayList<String>();var issued=new Context[1];var source=new View[1];
        var members=java.util.stream.IntStream.range(0,64).mapToObj(i->new Member(String.format(Locale.ROOT,"d%03d",i),"Division "+i,"대기 중","unit_hud/infantry","소속: A",.8,new Open(Mode.ARMY_UNITS,"A",List.of("unit/"+String.format(Locale.ROOT,"d%03d",i))))).toList();
        net.minecraft.client.sounds.SoundEventListener listener=(sound,event,range)->{if(sound.getIdentifier().getPath().equals("ui.division.select"))sounds.add("select");};
        try{
            game.getInput().resizeWindow(1280,720);
            game.runOnClient(client->{client.options.guiScale().set(2);MapCommanderHud.reset();MapUnitHud.reset();ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderOrders.selectionObserver=selections::add;MapCommanderOrders.commandObserver=c->{};client.getSoundManager().addListener(listener);source[0]=new View("KOR",client.level.dimension().identifier().toString(),Mode.ARMY,List.of(new Card("A","Army A","","politics/empty/leader","","",64,24,"",Mode.ASSIGN_ARMY,new Panel("","",null,members.subList(0,1),64,List.of(),members.stream().map(Member::id).toList()))));MapCommanderHud.accept(source[0]);issued[0]=new Context(UUID.randomUUID().toString(),0,"KOR",source[0].dimension(),"");MapCommanderOrders.accept(issued[0]);});
            game.setScreen(ScreenMapCursor::new);game.waitTicks(2);
            game.runOnClient(client->{var card=MapCommanderHud.boxes().stream().filter(b->b.request()!=null&&b.request().mode()==Mode.ASSIGN_ARMY).findFirst().orElseThrow();MapCommanderHud.clickAt(card.x()+card.width()/2.,card.y()+card.height()/2.);if(sounds.size()!=1)throw new AssertionError("A physical Army card selection plays its selection sound once");var sequence=selections.getLast().sequence();MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),sequence,1,32,64,members.subList(32,64)));if(rows().size()!=1)throw new AssertionError("Partial pages cannot publish incomplete selection details");MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),sequence,1,0,64,members.subList(0,32)));if(rows().size()!=64||MapCommanderPanels.commandSelection().size()!=64)throw new AssertionError("Full authoritative selection details include members beyond the card's limited preview");});game.waitTicks(2);
            var previousScroll=new int[1];
            game.runOnClient(client->{var row=MapCommanderPanels.hits().stream().filter(h->h.tip().contains("Division 0§!\n")).findFirst().orElseThrow();MapCommanderHud.scrollAt(row.x()+1,row.y()+1,-1);previousScroll[0]=scroll();if(previousScroll[0]==0)throw new AssertionError("Actual panel wheel must scroll the selected rows");});game.waitTicks(45);
            game.runOnClient(client->{MapCommanderHud.accept(source[0]);MapCommanderOrders.accept(issued[0]);if(scroll()!=previousScroll[0]||rows().size()!=64||sounds.size()!=1)throw new AssertionError("Delayed refresh retains the selection and scroll without replaying audio");});game.waitTicks(2);
            game.runOnClient(client->{var row=MapCommanderPanels.hits().stream().filter(h->h.tip().contains("Division 3§!\n")).findFirst().orElseThrow();MapCommanderHud.clickAt(row.x()+1,row.y()+1);if(sounds.size()!=2||!rows().equals(Set.of("d003")))throw new AssertionError("Individual left click selects and sounds exactly once without widening to its Army");});game.waitTicks(2);
            game.runOnClient(client->{if(MapCommanderPanels.hits().stream().filter(h->h.tip().contains("Division ")).count()<=1||!MapCommanderPanels.commandSelection().equals(List.of("unit/d003")))throw new AssertionError("The army list must retain unselected rows while commands target only the selected division");});game.takeScreenshot("hoi-army-list-partial-selection-gui2");
            game.runOnClient(client->{MapUnitHud.selectDivisions(List.of("d003","d010"),false);long seq=selections.getLast().sequence();MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),seq-1,2,0,1,List.of(members.get(0))));if(!rows().equals(Set.of("d003","d010")))throw new AssertionError("A delayed previous selection cannot replace current IDs");MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),seq,3,0,2,List.of(members.get(3),members.get(10))));MapCommanderHud.accept(source[0]);if(!rows().equals(Set.of("d003","d010"))||sounds.size()!=2)throw new AssertionError("Multi-selection refresh preserves only selected IDs and never plays selection audio");});game.waitTicks(2);game.takeScreenshot("hoi-selected-divisions-only-gui2");
            game.runOnClient(client->{long seq=selections.getLast().sequence();MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),seq,4,0,0,List.of()));if(!MapCommanderPanels.commandSelection().isEmpty()||!rows().isEmpty())throw new AssertionError("Authoritative loss of all selected units clears their private details");MapUnitHud.replaceKeys(List.of("stack|infantry"));MapCommanderPanels.mapSelectionChanged();var loose=new Member("loose","Unassigned division","대기 중","unit_hud/infantry","미배속",1,new Open(Mode.ARMY_UNITS,"",List.of("unit/loose")));MapCommanderOrders.acceptDetails(new DetailPage(issued[0].token(),selections.getLast().sequence(),5,0,1,List.of(loose)));if(!MapCommanderPanels.commandSelection().equals(List.of("unit/loose"))||!rows().equals(Set.of("loose"))||!MapCommanderPanels.selectedCards().isEmpty())throw new AssertionError("An unassigned map selection receives its stable ID and own detail without creating Army membership");});game.waitTicks(2);game.takeScreenshot("hoi-unassigned-selection-detail-gui2");
            game.runOnClient(client->{
                var missing=new Card("missing","Loading Army","","politics/empty/leader","","",1,24,"",Mode.ASSIGN_ARMY);
                MapCommanderHud.accept(new View("KOR",source[0].dimension(),Mode.ARMY,List.of(missing)));MapCommanderPanels.select(missing.id(),true);
                if(!MapCommanderPanels.commandSelection().equals(List.of("unit/loose")))throw new AssertionError("Missing card membership cannot erase an explicitly selected unassigned division");
                var old=selections.getLast();MapCommanderHud.accept(new View("",source[0].dimension(),Mode.ARMY,List.of()));MapCommanderOrders.acceptDetails(new DetailPage(old.token(),old.sequence(),6,0,1,List.of(members.getFirst())));if(!MapCommanderPanels.commandSelection().isEmpty()||!rows().isEmpty()||MapCommanderOrders.ready())throw new AssertionError("Revoked lobby context rejects late selection detail pages");
            });
        }finally{game.runOnClient(client->{client.getSoundManager().removeListener(listener);MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});}
    }
    private static void branches(ClientGameTestContext game,ProtocolMenuView menu){
        String directory=System.getenv("HOI_COMMANDER_PREVIEW");if(directory==null)return;
        try{for(String branch:List.of("navy","air")){
            var source=new Snapshot(java.nio.file.Files.readString(java.nio.file.Path.of(directory,"kor-command-panel-"+branch+".json"))).view();boolean navy=branch.equals("navy");var member=navy?source.cards().getFirst().panel().members().getFirst():source.wings().getFirst();
            String key=navy?member.id()+"|navy_destroyer":member.selectionKey();if(key.isEmpty())throw new AssertionError("Actual branch counter key is required");
            var played=new ArrayList<String>();net.minecraft.client.sounds.SoundEventListener listener=(sound,event,range)->{if(sound.getIdentifier().getPath().equals(navy?"ui.fleet.select":"ui.aircraft.select"))played.add("select");};
            game.runOnClient(client->{MapCommanderHud.reset();MapUnitHud.reset();ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));MapCommanderOrders.selectionObserver=x->{};MapCommanderOrders.commandObserver=x->{};MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings()));MapCommanderOrders.accept(new Context(UUID.randomUUID().toString(),0,"KOR",client.level.dimension().identifier().toString(),""));client.player.setXRot(0);client.player.setYRot(0);var at=client.player.getEyePosition().add(0,0,8);int split=key.lastIndexOf('|');MapUnitHud.accept(new ProtocolUnitHud.Snapshot(client.level.dimension().identifier().toString(),List.of(new ProtocolUnitHud.Counter(key.substring(0,split),"KOR","한국",key.substring(split+1),member.name(),1,at.x,at.y,at.z,1,1,1,Map.of()))));client.getSoundManager().addListener(listener);});
            try{
                game.setScreen(ScreenMapCursor::new);game.waitTicks(2);
                game.runOnClient(client->{var box=MapUnitHud.boxes().getFirst();if(!MapUnitHud.selectAt(box.x()+box.width()/2.,box.y()+box.height()/2.)||played.size()!=1)throw new AssertionError("Actual "+branch+" counter left click must play selection sound exactly once");var ids=MapCommanderPanels.commandSelection();if(navy&&!ids.equals(List.of("navy/"+member.id()))||!navy&&(ids.isEmpty()||ids.stream().anyMatch(id->!id.startsWith("air/")||id.contains("|"))))throw new AssertionError("Map counter selection must resolve to stable owned branch IDs: "+ids);});
                var ids=game.computeOnClient(client->MapCommanderPanels.commandSelection());game.waitTicks(45);
                game.runOnClient(client->{MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),source.cards(),source.wings()));if(!ids.equals(MapCommanderPanels.commandSelection())||played.size()!=1)throw new AssertionError("Branch details and stable IDs survive delayed refresh without audio replay");});game.waitTicks(2);
                game.runOnClient(client->{if(MapCommanderPanels.hits().isEmpty())throw new AssertionError("Selected branch must retain its left details");});game.takeScreenshot("hoi-map-selected-"+branch+"-details-gui2");
                if(!navy)game.runOnClient(client->{var replacement=new Member("new-wing",member.name(),member.status(),member.icon(),member.detail(),member.strength(),new Open(Mode.AIR_MISSION,"new-wing",List.of()),key,member.organization(),member.composition(),member.group(),member.mission(),member.data());var updated=new ArrayList<>(source.wings());updated.add(replacement);MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),source.cards(),updated));if(!ids.equals(MapCommanderPanels.commandSelection()))throw new AssertionError("A new wing sharing a previous counter must not join an existing stable selection");MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),source.cards(),List.of(replacement)));if(!MapCommanderPanels.commandSelection().isEmpty()||MapCommanderPanels.counterSelected(key))throw new AssertionError("A replaced air counter cannot inherit the removed wing's selection or highlight");});
                if(navy)game.runOnClient(client->{
                    var card=source.cards().getFirst();var panel=card.panel();var partial=new Panel(panel.parent(),panel.commander(),panel.leader(),List.of(),panel.total(),panel.controls());
                    var changed=new ArrayList<>(source.cards());changed.set(0,new Card(card.id(),card.name(),card.leader(),card.portrait(),card.marshal(),card.marshalPortrait(),card.count(),card.capacity(),card.detail(),card.role(),partial));
                    MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),changed,List.of()));
                    if(!MapCommanderPanels.commandSelection().equals(ids))throw new AssertionError("Incomplete fleet membership cannot delete an explicitly selected map force");
                    MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),source.cards(),List.of()));
                });
                game.runOnClient(client->{MapCommanderHud.accept(new View("KOR",client.level.dimension().identifier().toString(),source.branch(),navy?List.of():source.cards(),List.of()));if(!MapCommanderPanels.commandSelection().isEmpty()||MapCommanderPanels.counterSelected(key))throw new AssertionError("Removed branch selection must not widen or retain a stale counter highlight");});
            }finally{game.runOnClient(client->client.getSoundManager().removeListener(listener));}
        }}catch(java.io.IOException error){throw new AssertionError(error);}finally{game.runOnClient(client->{MapCommanderOrders.commandObserver=null;MapCommanderOrders.selectionObserver=null;MapCommanderHud.reset();MapUnitHud.reset();});}
    }

}
